/**
 * @cipherbox/crypto - Vault IPNS Key Derivation
 *
 * Derives a deterministic Ed25519 IPNS keypair for the user's vault
 * from the user's secp256k1 privateKey using HKDF-SHA256.
 *
 * Derivation path:
 *   secp256k1 privateKey (32 bytes)
 *     -> HKDF-SHA256(salt="CipherBox-v1", info="cipherbox-vault-ipns-v1")
 *     -> 32-byte Ed25519 seed
 *     -> Ed25519 keypair
 *     -> IPNS name (k51...)
 *
 * This enables self-sovereign vault recovery: recovery phrase -> privateKey
 * -> derive vault IPNS key -> resolve IPNS -> decrypt vault.
 *
 * Domain separation: Uses "cipherbox-vault-ipns-v1" info (different from
 * registry's "cipherbox-device-registry-ipns-v1"), ensuring the same
 * privateKey produces different IPNS keypairs for vault vs registry.
 */

import { deriveKey } from '../keys/derive';
import * as ed from '@noble/ed25519';
import { deriveIpnsName } from '../ipns/derive-name';
import { CryptoError } from '../types';
import { SECP256K1_PRIVATE_KEY_SIZE } from '../constants';

const VAULT_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
const VAULT_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-ipns-v1');
const VAULT_KEY_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-key-ipns-v1');
const BYO_CONFIG_HKDF_INFO = new TextEncoder().encode('cipherbox-byo-ipfs-config-v1');
const VAULT_SETTINGS_HKDF_INFO = new TextEncoder().encode('cipherbox-vault-settings-v1');

/**
 * Derive the deterministic Ed25519 IPNS keypair for the user's vault.
 *
 * Given the same secp256k1 privateKey, this always produces the same
 * IPNS name, enabling vault discovery from any device with the user's key.
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for the vault
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveVaultIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  // Validate input key length
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for vault derivation', 'INVALID_KEY_SIZE');
  }

  // 1. HKDF: secp256k1 privateKey -> 32-byte Ed25519 seed
  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: VAULT_HKDF_SALT,
    info: VAULT_HKDF_INFO,
    outputLength: 32,
  });

  // 2. Derive Ed25519 public key from seed (deterministic)
  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);

  // 3. Derive IPNS name from Ed25519 public key (k51... format)
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

/**
 * Derive a dedicated Ed25519 IPNS keypair for the vault key blob.
 *
 * This IPNS name stores the v2 blob containing the ECIES-wrapped rootFolderKey.
 * It is separate from the root folder IPNS name (which stores standard v1 folder
 * metadata) to avoid folder publishes overwriting the key blob.
 *
 * Uses "cipherbox-vault-key-ipns-v1" info for domain separation from the root
 * folder's "cipherbox-vault-ipns-v1".
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for the vault key blob
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveVaultKeyIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for vault key derivation', 'INVALID_KEY_SIZE');
  }

  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: VAULT_HKDF_SALT,
    info: VAULT_KEY_HKDF_INFO,
    outputLength: 32,
  });

  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

/**
 * Derive a dedicated Ed25519 IPNS keypair for BYO-IPFS config storage.
 *
 * This IPNS name stores the encrypted BYO-IPFS configuration (pinning mode,
 * external node endpoint, auth token). Zero-knowledge: the server never sees
 * the plaintext config.
 *
 * Uses "cipherbox-byo-ipfs-config-v1" info for domain separation.
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for the BYO config
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveByoConfigIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for BYO config derivation', 'INVALID_KEY_SIZE');
  }

  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: VAULT_HKDF_SALT,
    info: BYO_CONFIG_HKDF_INFO,
    outputLength: 32,
  });

  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

/**
 * Derive a dedicated Ed25519 IPNS keypair for vault settings storage.
 *
 * This IPNS name stores the encrypted user-configurable vault parameters
 * (retention period, delete behavior, versioning limits). Zero-knowledge:
 * the server never sees the plaintext settings.
 *
 * Uses "cipherbox-vault-settings-v1" info for domain separation.
 *
 * @param userPrivateKey - 32-byte secp256k1 private key
 * @returns Ed25519 keypair and IPNS name for vault settings
 * @throws CryptoError if the private key is not 32 bytes
 */
export async function deriveVaultSettingsIpnsKeypair(userPrivateKey: Uint8Array): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError(
      'Invalid private key size for vault settings derivation',
      'INVALID_KEY_SIZE',
    );
  }

  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: VAULT_HKDF_SALT,
    info: VAULT_SETTINGS_HKDF_INFO,
    outputLength: 32,
  });

  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

